#### Tenant Context Management

```python
from typing import Optional, Dict, Any
from contextlib import contextmanager
from contextvars import ContextVar
import asyncio

# Tenant context for request-scoped isolation
tenant_context: ContextVar[Optional[str]] = ContextVar('tenant_context', default=None)

class TenantContextManager:
    """Manages tenant context throughout request lifecycle"""

    @staticmethod
    def set_tenant(tenant_id: str) -> None:
        """Set current tenant context"""
        tenant_context.set(tenant_id)

    @staticmethod
    def get_tenant() -> Optional[str]:
        """Get current tenant context"""
        return tenant_context.get()

    @staticmethod
    def require_tenant() -> str:
        """Get tenant context or raise error if not set"""
        tenant_id = tenant_context.get()
        if not tenant_id:
            raise ValueError("Tenant context not set")
        return tenant_id

    @staticmethod
    @contextmanager
    def tenant_scope(tenant_id: str):
        """Context manager for tenant-scoped operations"""
        token = tenant_context.set(tenant_id)
        try:
            yield tenant_id
        finally:
            tenant_context.reset(token)

# Middleware for tenant context extraction
from fastapi import Request, HTTPException
from fastapi.middleware.base import BaseHTTPMiddleware

class TenantMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        # Extract tenant from various sources
        tenant_id = self._extract_tenant(request)

        if not tenant_id:
            raise HTTPException(status_code=400, detail="Tenant not specified")

        # Validate tenant exists and is active
        if not await self._validate_tenant(tenant_id):
            raise HTTPException(status_code=404, detail="Tenant not found")

        # Set tenant context
        TenantContextManager.set_tenant(tenant_id)

        response = await call_next(request)
        return response

    def _extract_tenant(self, request: Request) -> Optional[str]:
        """Extract tenant ID from request"""
        # Priority order: header, subdomain, path parameter, query parameter

        # 1. Custom header
        tenant_id = request.headers.get('X-Tenant-ID')
        if tenant_id:
            return tenant_id

        # 2. Subdomain extraction
        host = request.headers.get('host', '')
        if '.' in host:
            subdomain = host.split('.')[0]
            if subdomain != 'www' and subdomain != 'api':
                return subdomain

        # 3. Path parameter
        if hasattr(request, 'path_params'):
            tenant_id = request.path_params.get('tenant_id')
            if tenant_id:
                return tenant_id

        # 4. Query parameter
        return request.query_params.get('tenant_id')

