#### Database-Level Tenant Isolation

```python
from sqlalchemy import Column, String, DateTime, Boolean, Index, event
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker, Session
from sqlalchemy.sql import Select
import uuid
from datetime import datetime

Base = declarative_base()

class TenantMixin:
    """Mixin to add tenant isolation to database models"""
    tenant_id = Column(String(36), nullable=False, index=True)
    created_at = Column(DateTime, default=datetime.utcnow, nullable=False)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow, nullable=False)
    is_deleted = Column(Boolean, default=False, nullable=False)

class User(Base, TenantMixin):
    __tablename__ = 'users'

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    email = Column(String(255), nullable=False)
    first_name = Column(String(100), nullable=False)
    last_name = Column(String(100), nullable=False)
    is_active = Column(Boolean, default=True, nullable=False)

    # Composite indexes for tenant isolation
    __table_args__ = (
        Index('idx_users_tenant_email', 'tenant_id', 'email', unique=True),
        Index('idx_users_tenant_active', 'tenant_id', 'is_active'),
        Index('idx_users_tenant_deleted', 'tenant_id', 'is_deleted'),
    )

class TenantAwareSession:
    """Database session with automatic tenant filtering"""

    def __init__(self, session: Session):
        self.session = session
        self._setup_tenant_filtering()

    def _setup_tenant_filtering(self):
        """Set up automatic tenant filtering on queries"""
        @event.listens_for(Select, 'before_select')
        def receive_before_select(select, select_context):
            # Automatically add tenant filter to all queries
            tenant_id = TenantContextManager.get_tenant()
            if tenant_id and hasattr(select.table, 'c') and 'tenant_id' in select.table.c:
                select = select.where(select.table.c.tenant_id == tenant_id)
                select = select.where(select.table.c.is_deleted == False)

    def query(self, *args, **kwargs):
        """Query with automatic tenant filtering"""
        query = self.session.query(*args, **kwargs)

        # Add tenant filter for models with TenantMixin
        for desc in query.column_descriptions:
            if hasattr(desc['type'], '__table__') and 'tenant_id' in desc['type'].__table__.columns:
                tenant_id = TenantContextManager.require_tenant()
                query = query.filter(desc['type'].tenant_id == tenant_id)
                query = query.filter(desc['type'].is_deleted == False)

        return query

    def add(self, instance):
        """Add instance with automatic tenant assignment"""
        if hasattr(instance, 'tenant_id'):
            instance.tenant_id = TenantContextManager.require_tenant()
        return self.session.add(instance)

    def __getattr__(self, name):
        """Delegate to underlying session"""
        return getattr(self.session, name)

# Repository pattern with tenant awareness
class TenantAwareRepository:
    def __init__(self, model_class, session: TenantAwareSession):
        self.model_class = model_class
        self.session = session

    def get_by_id(self, id: str):
        """Get entity by ID within tenant scope"""
        return self.session.query(self.model_class).filter(
            self.model_class.id == id
        ).first()

    def list(self, limit: int = 100, offset: int = 0):
        """List entities within tenant scope"""
        return self.session.query(self.model_class).offset(offset).limit(limit).all()

    def create(self, **kwargs):
        """Create entity within tenant scope"""
        instance = self.model_class(**kwargs)
        self.session.add(instance)
        self.session.commit()
        return instance

    def update(self, id: str, **kwargs):
        """Update entity within tenant scope"""
        instance = self.get_by_id(id)
        if not instance:
            raise ValueError(f"Entity {id} not found")

        for key, value in kwargs.items():
            setattr(instance, key, value)

        self.session.commit()
        return instance

    def delete(self, id: str):
        """Soft delete entity within tenant scope"""
        instance = self.get_by_id(id)
        if not instance:
            raise ValueError(f"Entity {id} not found")

        instance.is_deleted = True
        self.session.commit()
